/**
 * Saved-card payment driver (Cinépolis -> DEUNA vault -> handlerComplete), deterministic.
 *
 * Observed on 2026-10-20 (purchase by hand with a saved Mastercard, no 3DS):
 *   UserSessionDeuna -> payment_methods -> DEUNA fraud id (Cybersource +
 *   Riskified, generated by DEUNA's own web SDK) -> vault iframe with the saved
 *   card -> CVV -> vault refresh-cvv (204) + "vaultSaveSuccess" postMessage ->
 *   handlerComplete (the charge) -> OrderDispatcher.
 *
 * The API-made hold has no state in the site's SPA, so instead of the site's
 * checkout page the bot opens cinepolis.com in its HEADED Chrome and embeds the
 * same DEUNA vault iframe and SDK there, with the same parameters the site
 * uses. Fingerprints and the CVV refresh therefore come from DEUNA's own code
 * in a real browser. The CVV is typed into the vault and never leaves memory.
 *
 * The charge is ONE server-side handlerComplete call, never retried:
 *   - booking returned            -> paid
 *   - Cinépolis answered an error -> OrderDispatcher check: booking -> paid;
 *                                    any status -> unknown (keep seats);
 *                                    nothing   -> failed, release seats
 *   - no answer / 5xx / timeout   -> OrderDispatcher check; else unknown
 * Everything before the charge that fails releases the seats (nothing charged).
 */
import type { GraphQLClient } from "../cinepolis/client.js";
import type { Hold, HoldService } from "../cinepolis/orders.js";
import { HANDLER_COMPLETE, PAYMENT_METHODS, USER_SESSION_DEUNA } from "../cinepolis/queries.js";
import { CinesError } from "../errors.js";
import { fetchBooking, type Booking, type Buyer } from "./paypal.js";
import type { PaymentContext, PaymentDriver, PaymentMethod, PaymentResult } from "./purchase.js";

export const CARD_KEY = "bank_card_deuna";
export const CARD_3DS_KEY = "bank_card_3ds";
/** Plain-Spanish refusal when the bank asks for 3-D Secure (not supported yet). */
export const MSG_3DS = "Tu banco pidió una verificación extra (3-D Secure) que todavía no puedo hacer; no cobré nada y liberé los asientos. Intenta con PayPal o desde la app de Cinépolis.";
const RE_3DS = /3-?d\s*secure|3ds|autenticaci[oó]n|challenge/i;

export const DEUNA_SDK_URL = "https://cdn.deuna.io/web-sdk/v1.6/index.js";

export interface PaymentMethodInfo {
  key: string;
  enabled: boolean;
  iframeUrl?: string;
  publicKey?: string;
  env?: string;
  /** Fraud providers as the site passes them to DeunaSDK.generateFraudId. */
  fraud: { CYBERSOURCE?: { orgId: string; merchantId: string }; RISKIFIED?: { storeDomain: string } };
}

export interface SavedCard {
  lastFour: string;
  isDefault?: boolean;
  expired?: boolean;
  /** Currently selected in the vault's pay view. */
  selected?: boolean;
}

/** Non-secret card data the vault posts back after the CVV refresh. */
export interface VaultCard {
  id: string;
  firstSix?: string;
  lastFour?: string;
  company?: string;
  cardType?: string;
}

export interface CardSession {
  /** Saved cards the vault shows (lists all when `all`, else just the selected one). */
  cards(all?: boolean): Promise<SavedCard[]>;
  /** Switch the vault to this saved card (never touches delete / add-card controls). */
  selectCard(lastFour: string): Promise<void>;
  /** DEUNA's fraud/session id from its own SDK, or undefined if it could not be produced. */
  fraudId(): Promise<string | undefined>;
  /**
   * Type the CVV into the vault and press its "Pagar" (refresh-cvv only, not the charge).
   * Resolves with the vault's card data, or throws CINES_PAYMENT_FAILED on vaultSaveError.
   * Implementations must not log, store or echo `cvv`.
   */
  submitCvv(cvv: string): Promise<VaultCard>;
  screenshot(name: string): Promise<string | undefined>;
}

export interface CardUi {
  /** Open cinepolis.com headed, load DEUNA's SDK and the vault iframe, and run `fn`. */
  runCard<T>(opts: { vaultUrl: string; method: PaymentMethodInfo }, fn: (s: CardSession) => Promise<T>): Promise<T>;
}

export interface CardDriverDeps {
  client: GraphQLClient;
  holds: HoldService;
  accessToken: () => Promise<string>;
  buyer: () => Promise<Buyer>;
  ui: CardUi;
  /** Preferred saved card (CINES_CARD_LAST4); the purchase argument wins. */
  defaultLastFour?: string;
  now?: () => number;
  sleep?: (ms: number) => Promise<void>;
}

/** Card brand as the site sends it in payment_card_type. */
export function cardTypeFor(company?: string): string {
  switch ((company ?? "").toUpperCase()) {
    case "VISA":
      return "visa";
    case "AMERICAN_EXPRESS":
    case "AMEX":
      return "amex";
    case "MASTERCARD":
    case "MASTER":
      return "master";
    default:
      return (company ?? "").toLowerCase();
  }
}

/** The site's payment_fingerprint_fallback: vista_ordersession10_yymmddHHMM(UTC)_tickets. */
export function fingerprintFallback(vistaId: string, orderSessionId: string, tickets: number, at: Date): string {
  const stamp = at.toISOString().replace(/[-T:.Z]/g, "").slice(0, 12).substring(2);
  return `${vistaId}_${orderSessionId.replace(/-/g, "").slice(0, 10)}_${stamp}_${tickets}`;
}

/** Vault URL exactly as the site builds it for a logged-in user with saved cards. */
export function vaultUrl(m: PaymentMethodInfo, buyer: Buyer, userToken: string): string {
  const u = new URL(m.iframeUrl!);
  u.searchParams.set("publicApiKey", m.publicKey ?? "");
  u.searchParams.set("firstName", buyer.firstName);
  u.searchParams.set("lastName", buyer.lastName);
  u.searchParams.set("email", buyer.email);
  u.searchParams.set("showSavedCardsFlow", "true");
  u.searchParams.set("userToken", userToken);
  return u.toString();
}

interface RawMethod {
  key?: string | null;
  enabled?: boolean | null;
  settings?: { iframe_url?: string | null; public_key?: string | null; env?: string | null; profile?: { org_id?: string | null; merch?: string | null; provider?: string | null }[] | null } | null;
}

/** payment_methods for an order session (member API). Read-only. */
export async function paymentMethods(client: GraphQLClient, orderSessionId: string, accessToken: string): Promise<PaymentMethodInfo[]> {
  const r = await client.call<{ payment_methods: RawMethod[] | null }>(PAYMENT_METHODS, { orderSessionId, countryId: client.countryId }, { accessToken, noDedupe: true });
  return (r.payment_methods ?? []).map((m) => {
    const prof = m.settings?.profile ?? [];
    const cy = prof.find((p) => (p.provider ?? "").toLowerCase() === "cybersource");
    const rk = prof.find((p) => (p.provider ?? "").toLowerCase() === "riskified");
    return {
      key: m.key ?? "",
      enabled: m.enabled === true,
      iframeUrl: m.settings?.iframe_url || undefined,
      publicKey: m.settings?.public_key || undefined,
      env: m.settings?.env || undefined,
      fraud: {
        ...(cy ? { CYBERSOURCE: { orgId: cy.org_id ?? "", merchantId: cy.merch ?? "" } } : {}),
        ...(rk ? { RISKIFIED: { storeDomain: rk.merch ?? "" } } : {}),
      },
    };
  });
}

/** DEUNA user token for the vault (the site asks for it on every payment page). */
export async function deunaUserToken(client: GraphQLClient, buyer: Buyer, accessToken: string): Promise<string> {
  const r = await client.call<{ userSessionDeuna: { user_token?: string | null } | null }>(
    USER_SESSION_DEUNA,
    { first_name: buyer.firstName, last_name: buyer.lastName },
    { accessToken, noDedupe: true },
  );
  const t = r.userSessionDeuna?.user_token;
  if (!t) throw new CinesError("CINES_SCHEMA_CHANGED", "DEUNA no devolvió el token del monedero.");
  return t;
}

/** Pick the saved card: explicit choice > configured > the vault's selection (its default). */
export function chooseCard(cards: SavedCard[], wanted?: string): SavedCard {
  const usable = cards.filter((c) => !c.expired);
  if (wanted) {
    const c = cards.find((x) => x.lastFour === wanted);
    if (!c) throw new Error(`no tienes guardada una tarjeta terminada en ${wanted} (hay: ${cards.map((x) => `*${x.lastFour}`).join(", ") || "ninguna"})`);
    if (c.expired) throw new Error(`la tarjeta *${wanted} está vencida`);
    return c;
  }
  const c = usable.find((x) => x.selected) ?? usable.find((x) => x.isDefault) ?? (usable.length === 1 ? usable[0] : undefined);
  if (!c) throw new Error(usable.length ? `tienes varias tarjetas (${usable.map((x) => `*${x.lastFour}`).join(", ")}); indica cuál con cardLast4` : "no tienes tarjetas guardadas vigentes en Cinépolis");
  return c;
}

/** The card list can only be read for an order session with an active hold. */
export class CardCheckDeferred extends Error {
  constructor() {
    super("se verifica al apartar: Cinépolis solo da los métodos de pago para un apartado activo");
  }
}

/**
 * Read-only: the saved cards the vault would offer (preflight). Uses a fresh,
 * unused order-session id for payment_methods; nothing is held or charged and
 * no CVV is typed.
 */
export async function listSavedCards(d: { client: GraphQLClient; accessToken: () => Promise<string>; buyer: () => Promise<Buyer>; ui: CardUi }, orderSessionId: string): Promise<SavedCard[]> {
  const token = await d.accessToken();
  const buyer = await d.buyer();
  let methods: PaymentMethodInfo[];
  try {
    methods = await paymentMethods(d.client, orderSessionId, token);
  } catch (e) {
    // Live 2026-10-20: payment_methods answers 404 for an order session with no active cart.
    if (e instanceof CinesError && e.code === "CINES_BAD_REQUEST") throw new CardCheckDeferred();
    throw e;
  }
  const card = methods.find((m) => m.key === CARD_KEY && m.enabled);
  if (!card?.iframeUrl || !card.publicKey) throw new Error(methods.some((m) => m.key === CARD_3DS_KEY) ? "la cuenta usa tarjeta con 3-D Secure (no soportado aún)" : "Cinépolis no ofrece pago con tarjeta guardada");
  const userToken = await deunaUserToken(d.client, buyer, token);
  return d.ui.runCard({ vaultUrl: vaultUrl(card, buyer, userToken), method: card }, (s) => s.cards(true));
}

type Outcome = { kind: "charged"; booking: Booking } | { kind: "declined"; why: string } | { kind: "unknown"; why: string };

export class CardDriver implements PaymentDriver {
  readonly name = "card";
  constructor(private readonly d: CardDriverDeps) {}

  supports(method: PaymentMethod): boolean {
    return method === "card";
  }

  async pay(ctx: PaymentContext): Promise<PaymentResult> {
    const { hold, log } = ctx;
    const sleep = this.d.sleep ?? ((ms: number) => new Promise((r) => setTimeout(r, ms)));
    const now = this.d.now ?? Date.now;
    const unpaid = async (why: string, exact = false): Promise<never> => {
      await this.d.holds.releaseUnpaid(hold.holdId).catch((e: unknown) => log(`release failed: ${(e as Error).message}`));
      throw new CinesError("CINES_PAYMENT_FAILED", exact ? why : `${why} No se cobró nada y liberé los asientos.`);
    };
    const needs3ds = { flag: false };
    const wanted = ctx.cardLast4 ?? this.d.defaultLastFour;

    // 1. Payment method, DEUNA user token (read-only; nothing charged yet).
    let buyer: Buyer;
    let token: string;
    let method: PaymentMethodInfo;
    let userToken: string;
    try {
      buyer = await this.d.buyer();
      token = await this.d.accessToken();
      const methods = await paymentMethods(this.d.client, hold.priv.orderSessionId, token);
      const card = methods.find((m) => m.key === CARD_KEY && m.enabled);
      if (!card) {
        needs3ds.flag = methods.some((m) => m.key === CARD_3DS_KEY && m.enabled);
        throw new Error(needs3ds.flag ? "3-D Secure" : "Cinépolis no ofrece pago con tarjeta para esta compra");
      }
      if (!card.iframeUrl || !card.publicKey) throw new Error("faltan datos del monedero DEUNA en payment_methods");
      method = card;
      userToken = await deunaUserToken(this.d.client, buyer, token);
    } catch (e) {
      if (needs3ds.flag) return unpaid(MSG_3DS, true);
      return unpaid(`No pude preparar el pago con tarjeta (${(e as Error).message}).`);
    }
    log("card: payment method and wallet token ready");

    // 2-3. Vault in the headed bot browser: card, fraud id, CVV -> vault card data.
    let vault: VaultCard;
    let fraudId: string | undefined;
    let lastFour: string;
    try {
      ({ vault, fraudId, lastFour } = await this.d.ui.runCard({ vaultUrl: vaultUrl(method, buyer, userToken), method }, async (s) => {
        let pick: SavedCard;
        try {
          const shown = await s.cards(false);
          const all = wanted && !shown.some((c) => c.lastFour === wanted && !c.expired) ? await s.cards(true) : shown;
          pick = chooseCard(all, wanted);
          if (!pick.selected) await s.selectCard(pick.lastFour);
        } catch (e) {
          const shot = await s.screenshot("card-select");
          throw new CinesError("CINES_PAYMENT_FAILED", (e as Error).message, { detail: shot });
        }
        const fid = await s.fraudId().catch(() => undefined);
        if (!fid) log("card: DEUNA fraud id unavailable; sending the fallback fingerprint only");
        await this.d.holds.extendRemote(hold.holdId).catch(() => false);
        const secret = { cvv: await ctx.ask("cvv", `Escribe el CVV (3 o 4 dígitos) de tu tarjeta *${pick.lastFour} para pagar $${hold.totalMxn} MXN.`) };
        try {
          const v = await s.submitCvv(secret.cvv);
          return { vault: v, fraudId: fid, lastFour: pick.lastFour };
        } finally {
          secret.cvv = ""; // drop the only reference as soon as the vault has it
        }
      }));
    } catch (e) {
      const msg = e instanceof CinesError ? e.message : `La ventana del monedero falló (${(e as Error).message})`;
      if (RE_3DS.test(msg)) return unpaid(MSG_3DS, true);
      return unpaid(`No se completó el paso de la tarjeta: ${msg}.`);
    }
    if (!vault.id) return unpaid("El monedero DEUNA no confirmó la tarjeta.");
    log("card: vault confirmed the card; charging once");

    // 4. The charge: exactly one handlerComplete.
    const input = {
      cinema_id: hold.priv.cinemaVistaId,
      customer: { email: buyer.email, first_name: buyer.firstName, last_name: buyer.lastName },
      payment: {
        payment_method: CARD_KEY,
        payment_id: vault.id,
        payment_info: {
          payment_card_type: cardTypeFor(vault.company),
          payment_fingerprint: fraudId ?? "",
          payment_fingerprint_fallback: fingerprintFallback(hold.priv.cinemaVistaId, hold.priv.orderSessionId, hold.seats.length, new Date(now())),
          payment_last_four_digits: vault.lastFour ?? lastFour,
          payment_first_six_digits: vault.firstSix ?? "",
          payment_payer_id: "",
          payment_order_id: "",
          payment_retain_on_success: false,
          payment_card_category: vault.cardType ?? "credit_card",
        },
        payment_partial_active: false,
      },
      country_id: this.d.client.countryId,
      order_session_id: hold.priv.orderSessionId,
    };
    const outcome = await this.charge(hold, input, token, sleep);
    if (outcome.kind === "charged") {
      return { bookingNumber: outcome.booking.bookingNumber!, transactionNumber: outcome.booking.transactionNumber };
    }
    if (outcome.kind === "declined" && RE_3DS.test(outcome.why)) return unpaid(MSG_3DS, true);
    if (outcome.kind === "declined") return unpaid(`Cinépolis rechazó el pago con la tarjeta *${lastFour} (${outcome.why}).`);
    throw new CinesError("CINES_UNAVAILABLE", `El resultado del pago es incierto (${outcome.why}). No libero los asientos ni reintento; revisa tu correo de Cinépolis y tu banco.`, { retryable: false });
  }

  private async charge(hold: Hold, input: Record<string, unknown>, token: string, sleep: (ms: number) => Promise<void>): Promise<Outcome> {
    let answered: CinesError | undefined;
    try {
      const r = await this.d.client.call<{ handlerComplete: { bookingInfo: { booking_id?: string | null; booking_number?: string | null; trans_number?: string | null } | null } | null }>(
        HANDLER_COMPLETE,
        { input },
        { accessToken: token, noDedupe: true },
      );
      const b = r.handlerComplete?.bookingInfo;
      const bookingNumber = b?.booking_number || b?.booking_id || undefined;
      if (bookingNumber) return { kind: "charged", booking: { bookingNumber, transactionNumber: b?.trans_number || undefined } };
    } catch (e) {
      // A refusal Cinépolis answered (decline, bad session, contract change) vs. no reliable answer.
      if (e instanceof CinesError && ["CINES_BAD_REQUEST", "CINES_SESSION_EXPIRED", "CINES_NOT_FOUND", "CINES_SCHEMA_CHANGED"].includes(e.code)) answered = e;
      else return this.settle(hold, sleep, `sin respuesta clara de Cinépolis: ${(e as Error).message}`);
    }
    // Answered without a booking: confirm through OrderDispatcher before deciding.
    await sleep(3000);
    const b = await fetchBooking(this.d.client, hold.priv.orderSessionId);
    if (b?.bookingNumber) return { kind: "charged", booking: b };
    if (b?.status) return { kind: "unknown", why: `estado "${b.status}"` };
    if (!answered) return { kind: "unknown", why: "Cinépolis respondió sin boleto" };
    return { kind: "declined", why: answered.message.replace(/^Cinépolis rechazó handlerComplete: /, "") };
  }

  /** No reliable answer to the charge: poll for a booking a little, otherwise unknown. */
  private async settle(hold: Hold, sleep: (ms: number) => Promise<void>, why: string): Promise<Outcome> {
    for (let i = 0; i < 6; i++) {
      await sleep(5000);
      const b = await fetchBooking(this.d.client, hold.priv.orderSessionId);
      if (b?.bookingNumber) return { kind: "charged", booking: b };
    }
    return { kind: "unknown", why };
  }
}
